void MaybeShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  std::string gaia_signin = request->request_headers().find("X-Gaia-SignIn")->second;
  if (gaia_signin.empty())
    return;

  std::string realm = request->url().host();
  if (realm != "accounts.google.com" && realm != "www.google.com")
    return;

  std::istringstream iss(gaia_signin);
  std::string email, session_index;
  std::getline(iss, email, '\0');
  std::getline(iss, session_index, '\0');

  if (email.empty() && session_index.empty())
    return;

  io_data->email() = email;

  bool auto_accept = !session_index.empty() && (request->request_initiator().host() == "clients.google.com");

  content::GetUIThreadTaskRunner({})->PostTask(
      FROM_HERE,
      base::BindOnce(
          [](ProfileIOData* io_data, int child_id, int route_id, const std::string& email, const std::string& session_index, bool auto_accept) {
            ShowOneClickSignInInfoBar(email, session_index, auto_accept, child_id, route_id);
          },
          io_data, child_id, route_id, email, session_index, auto_accept));
}

void CheckAndDisplaySignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& headers = request->extra_request_headers().GetHeader(net::HttpRequestHeaders::kXRequestedWith);
  if (headers.empty()) {
    return;
  }

  GURL url = request->url();
  if (!url.SchemeIs("https") || !url.DomainIs("accounts.google.com")) {
    return;
  }

  std::string email, session_index;
  if (!ParseSignInValuesFromHeaders(request->extra_request_headers(), &email, &session_index)) {
    return;
  }

  if (email.empty() && session_index.empty()) {
    return;
  }

  bool auto_accept = ShouldAutoAcceptSignIn(email, session_index, request);

  io_data->task_runner()->PostTask(
      FROM_HERE,
      base::BindOnce(&DisplaySignInInfoBarOnUIThread, child_id, route_id, email, session_index, auto_accept));
}

void ShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  std::string sign_in_values = request->request_headers().GetHeader("X-Chrome-OAuth2-Signin");
  if (sign_in_values.empty())
    return;

  GURL url(request->url());
  if (!url.SchemeIs("https") || !url.DomainIs("accounts.google.com"))
    return;

  std::string email, session_index;
  size_t pos = sign_in_values.find(',');
  if (pos != std::string::npos) {
    email = sign_in_values.substr(0, pos);
    session_index = sign_in_values.substr(pos + 1);
  }

  bool auto_accept = !email.empty() && !session_index.empty();

  if (email.empty() && session_index.empty())
    return;

  BrowserThread::PostTask(
      BrowserThread::UI,
      FROM_HERE,
      base::Bind(&ShowOneClickSignInInfoBarOnUIThread, email, session_index, auto_accept, child_id, route_id));
}

void ShowSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& headers = request->extra_request_headers().GetHeader(
      "X-Chrome-OAuth2-Signin", std::string());
  if (headers.empty())
    return;

  GURL url(request->url());
  if (!url.SchemeIs("https") || !url.host().ends_with(".google.com"))
    return;

  std::string email, session_index;
  size_t pos = headers.find(':');
  if (pos != std::string::npos) {
    email = headers.substr(0, pos);
    session_index = headers.substr(pos + 1);
  }

  if (email.empty() && session_index.empty())
    return;

  bool auto_accept = !email.empty() && !session_index.empty();

  io_data->task_runner()->PostTask(
      FROM_HERE,
      base::BindOnce(&ShowSignInInfoBarOnUIThread, child_id, route_id, email, session_index, auto_accept));
}

void ShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& sign_in_header = request->request_headers().FindHeader("X-Chrome-Signin");
  if (sign_in_header.empty())
    return;

  // Parse the sign-in values from the header.
  std::vector<std::string> sign_in_values = base::SplitString(sign_in_header, ";", base::TRIM_WHITESPACE, base::SPLIT_WANT_ALL);
  std::string email;
  std::string session_index;

  for (const std::string& value : sign_in_values) {
    if (base::StartsWith(value, "email=")) {
      email = value.substr(6);
    } else if (base::StartsWith(value, "session_index=")) {
      session_index = value.substr(14);
    }
  }

  if (email.empty() && session_index.empty())
    return;

  // Check if the request URL is for the Gaia sign-on realm.
  const GURL& url = request->url();
  if (!url.SchemeIs("https") || !url.DomainIs("accounts.google.com")) {
    return;
  }

  bool auto_accept = !email.empty() && !session_index.empty();

  // If all values are default, return early.
  if (!auto_accept)
    return;

  // Post a task to the UI thread to show the info bar.
  io_data->io_task_runner()->PostTask(
      FROM_HERE,
      base::BindOnce(&ShowOneClickSignInInfoBarOnUIThread, child_id, route_id, email, session_index));
}
